def parse_header_params(header_value: str):
    """
    Parse a header value into its main value and parameters.

    Args:
        header_value: The header value string to parse.

    Returns:
        A tuple of (main_value, dict_of_parameters).
    """
    if not header_value:
        return ('', {})

    # Split on semicolons to get the main value and parameters
    parts = header_value.split(';')

    # The first part is the main value
    main_value = parts[0].strip()

    params = {}

    for part in parts[1:]:
        part = part.strip()
        if not part:
            continue

        if '=' in part:
            key, value = part.split('=', 1)
            key = key.strip()
            value = value.strip()

            # Strip wrapping quotes from value if present
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]

            params[key] = value
        else:
            # No '=' found, treat key with empty value
            key = part.strip()
            if key:
                params[key] = ''

    return (main_value, params)
